const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').split(/\s+/).filter(x => x.length);
let idx = 0;
const N = parseInt(data[idx++]);
const M = parseInt(data[idx++]);
const G = [];
for (let i = 0; i < N; i++) {
  const row = [];
  for (let j = 0; j < M; j++) row.push(parseInt(data[idx++]));
  G.push(row);
}

// Para uma orientação do tabuleiro (paridade alvo em (0,0) = p):
// célula (i,j) alvo parity = p ^ ((i+j) & 1)
// custo = 1 se (G[i][j] & 1) !== alvo, senão 0
function costAndGrid(p) {
  let cost = 0;
  const res = [];
  for (let i = 0; i < N; i++) {
    const row = [];
    for (let j = 0; j < M; j++) {
      const target = p ^ ((i + j) & 1);
      const cur = G[i][j] & 1;
      if (cur !== target) {
        cost++;
        row.push(G[i][j] + 1);
      } else {
        row.push(G[i][j]);
      }
    }
    res.push(row);
  }
  return { cost, res };
}

const a = costAndGrid(0);
const b = costAndGrid(1);
const best = a.cost <= b.cost ? a : b;

let out = [];
out.push(String(best.cost));
for (let i = 0; i < N; i++) out.push(best.res[i].join(' '));
console.log(out.join('\n'));
